import{_ as t,o as a,c as s,ag as d}from"./chunks/framework.CfmR1glF.js";const m=JSON.parse('{"title":"主题与 CSS variables","description":"","frontmatter":{},"headers":[],"relativePath":"guide/theme.md","filePath":"guide/theme.md"}'),o={name:"guide/theme.md"};function i(r,e,c,l,n,p){return a(),s("div",null,[...e[0]||(e[0]=[d(`<h1 id="主题与-css-variables" tabindex="-1">主题与 CSS variables <a class="header-anchor" href="#主题与-css-variables" aria-label="Permalink to &quot;主题与 CSS variables&quot;">​</a></h1><p>完整 TS/JS SFC 与可交互结果见 <a href="/theme.html">主题与四档尺寸示例</a>。文档采用固定 Element Plus 2.14.7 与 ASAM 四档契约；颜色、边框、文字由 tokens 承接，不另造同名空组件。</p><p>先加载 <code>element-plus/dist/index.css</code>，再加载 <code>@asam-ui/ui/style.css</code>。默认样式从 <code>--asam-*</code> 语义变量读取颜色、文字、边框、圆角、间距和尺寸，并把常用 Element Plus 变量映射到相同语义。查看 <strong>设计系统/基础色板</strong> 和 <strong>设计系统/主题覆盖示例</strong> 的实时结果。</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { applyAsamTheme, createAsamTheme } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@asam-ui/ui/tokens&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">applyAsamTheme</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">createAsamTheme</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ color: { primary: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;#0f766e&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } }));</span></span></code></pre></div><p>只覆盖 <code>color.primary</code> 时，hover、active 与渐变起点随之推导；也可分别指定。传入目标元素可把变量限定在局部容器：</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> scope</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> document.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">querySelector</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">HTMLElement</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;#preview&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (scope) </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">applyAsamTheme</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">createAsamTheme</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ color: { primary: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;#0f766e&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } }), scope);</span></span></code></pre></div><p>也可在安装时传 <code>app.use(AsamUI, { theme, target })</code>。默认写入 <code>document.documentElement</code>；局部 target 只影响其 DOM 后代，挂到 body 的弹出层仍继承全局变量。页面级样式应使用 <code>--asam-*</code>，不依赖内部生成类名。可通过 <code>defaultAsamTheme</code> 与 <code>toAsamCssVariables</code> 查询完整当前变量集；手写变量清单会随 tokens 变化而过期。</p><p>字体栈优先列出思源黑体，但包没有附带字体文件。字符串 <code>icon</code> 是兼容属性，不自动加载图标运行时；需要可见图标时传组件或 <code>icon</code> slot。</p><h2 id="公开主题接口" tabindex="-1">公开主题接口 <a class="header-anchor" href="#公开主题接口" aria-label="Permalink to &quot;公开主题接口&quot;">​</a></h2><p><code>@asam-ui/ui/tokens</code> 导出 <code>defaultAsamTheme</code>、<code>createAsamTheme(overrides)</code>、<code>toAsamCssVariables(tokens)</code>、<code>applyAsamTheme(tokens?, target?)</code>、基础色板、设计值和四档密度。<code>AsamThemeTokens</code> 是完整对象类型，<code>DeepPartial&lt;AsamThemeTokens&gt;</code> 是覆盖类型，<code>AsamControlDensityTokens</code> 描述密度。完整返回对象与默认对象相互独立；传入 <code>undefined</code> 的覆盖字段保留默认值。<code>toAsamCssVariables</code> 将嵌套驼峰字段变为 <code>--asam-*</code> 字符串变量。<code>applyAsamTheme</code> 在同一目标再次应用时移除上次已写入而本次不存在的变量；服务端没有 document 且省略 target 时不执行 DOM 操作。</p><p><code>border</code>、<code>typography.lineHeight</code> 和 <code>density.*.formItemMarginBottom</code> 为可选新增字段，保留既有完整对象的类型兼容。用 <code>createAsamTheme</code> 获得包含默认新增字段的对象；旧手写对象缺省这些字段时 CSS 使用默认回退。覆盖的类型仍严格检查字段值，不能把数值传给 CSS 长度字段。</p><h2 id="颜色、边框与文字约定" tabindex="-1">颜色、边框与文字约定 <a class="header-anchor" href="#颜色、边框与文字约定" aria-label="Permalink to &quot;颜色、边框与文字约定&quot;">​</a></h2><table tabindex="0"><thead><tr><th>范围</th><th>ASAM 承接</th></tr></thead><tbody><tr><td>主要色与交互</td><td><code>color.primary / primaryHover / primaryActive / primaryGradientStart</code>；仅覆写 primary 会推导其余三个值</td></tr><tr><td>场景色</td><td><code>success / successStrong / warning / danger / info</code> 及其 hover/active；原始扩展色板在 <code>color.palette</code></td></tr><tr><td>中性色</td><td><code>textPrimary / textRegular / textSecondary</code>，<code>surface / surfacePage / surfaceMuted / surfaceSoft / surfaceInfo / surfaceSuccess</code>，<code>border / divider / shadow</code></td></tr><tr><td>边框样式</td><td><code>border.width=&#39;1px&#39;</code>、<code>border.style=&#39;solid&#39;</code>；需要虚线时显式使用 2px dashed，颜色来自 <code>--asam-color-border</code></td></tr><tr><td>圆角</td><td><code>radius.control / action / card / dialog / pill</code>；独立页面消费 <code>--asam-radius-*</code></td></tr><tr><td>阴影</td><td><code>shadow.card / dialog</code>，映射原生 normal/light/lighter/dark 变量；ASAM 语义阴影优先，不硬套原生外观值</td></tr><tr><td>字号与字重</td><td>xs/sm/md/lg/xl 为 12/13/14/16/20px；regular/medium/bold 为 400/500/700</td></tr><tr><td>文字行高</td><td>none/compact/regular/loose 为 1/1.3/1.5/1.7；控件高度保持尺寸契约，正文自行选行高</td></tr></tbody></table><p>暗色通过 <code>createAsamTheme</code> 覆盖 surface、text、border 和语义颜色后应用。示例提供完整局部暗色覆盖与亮暗切换；默认主题仍为既定亮色，不依赖 HTML 的 <code>.dark</code> 自动改变 ASAM tokens。使用原生 <code>dark/css-vars.css</code> 的宿主仍需将 ASAM 语义色与自己的主题一致配置。局部主题不改变 body 级 teleported 弹层；需要同色弹层时应用全局主题，或使用相应组件支持的容器/teleported 配置。</p><p>原生 <code>--el-color-error</code>、<code>error-light-3/5/7/8/9</code> 和 <code>error-dark-2</code> 与已有 danger 语义映射一致，默认、全局及局部主题都随当前 danger 变化；无需新增主题字段。原生 MessageBox 的 error 状态等直接消费这些变量的内容也沿用此映射。</p><p>六个 <code>--el-color-{primary,success,warning,danger,error,info}-rgb</code> tuple 保留 Element Plus 编译值；<code>applyAsamTheme</code> 首次应用与重复应用都不转换它们，也不承诺动态 RGB 转换 API。<code>rgba(var(--el-color-error-rgb), 0.16)</code> 使用原生 tuple，而 <code>var(--el-color-error)</code> 使用当前 danger 语义色。亮暗示例提供六个实际 tuple 消费面；默认、全局、局部和嵌套应用均验证此保留边界。需要当前语义色的透明背景时使用 <code>color-mix(in srgb, var(--asam-color-danger) 16%, transparent)</code>。</p><h2 id="四档尺寸与继承" tabindex="-1">四档尺寸与继承 <a class="header-anchor" href="#四档尺寸与继承" aria-label="Permalink to &quot;四档尺寸与继承&quot;">​</a></h2><table tabindex="0"><thead><tr><th>size</th><th style="text-align:right;">适用单行高度</th><th style="text-align:right;">Button 左右 padding</th></tr></thead><tbody><tr><td>large</td><td style="text-align:right;">40px</td><td style="text-align:right;">20px</td></tr><tr><td>big</td><td style="text-align:right;">36px</td><td style="text-align:right;">18px</td></tr><tr><td>default</td><td style="text-align:right;">32px</td><td style="text-align:right;">16px</td></tr><tr><td>small</td><td style="text-align:right;">28px</td><td style="text-align:right;">14px</td></tr></tbody></table><p>优先级为显式组件 size → 最近 Group → Form/FormItem → ConfigProvider → default。省略 scope 的 size 继续继承；响应式更新 provider 不覆盖更近的显式 Form/Group。数据包装复用同一个 ASAM injection key，不应复制 size context。big 只在传给原生 Element Plus 时桥接为 default，ASAM 后代与 <code>data-asam-size=&#39;big&#39;</code> 仍为 big。自定义组件可用 <code>useAsamControlSize</code> 和 <code>toElementPlusControlSize</code>，仅真实 scope 容器调用 <code>provideAsamControlSize</code>。</p><p>Textarea 高度由 rows/autosize 控制；Table、Descriptions、Pagination 等使用字号、图标、padding、gap 或 rowPadding 密度，不强制行高40/36/32/28。Icon/Avatar 的图形尺寸、Drawer 宽高、Space 间距、TimelineItem 节点大小继续保留各自 size 类型，不传四档字符串去替代数值尺寸。</p><h2 id="formitem-间距与布局工具类" tabindex="-1">FormItem 间距与布局工具类 <a class="header-anchor" href="#formitem-间距与布局工具类" aria-label="Permalink to &quot;FormItem 间距与布局工具类&quot;">​</a></h2><p>2.14.7 在每个 FormItem 上声明 <code>--el-form-item-margin-bottom</code>。ASAM 在同一 item 上将它桥接到 <code>--asam-form-item-margin-bottom</code>，避免只写父容器却被原生局部声明遮住。四档默认均消费既有 <code>layout.fieldGap=&#39;20px&#39;</code>；可通过 <code>density.big.formItemMarginBottom</code> 等覆写指定档位。局部旧完整主题省略新增间距字段时，<code>applyAsamTheme</code> 在本次目标上补四档 <code>var(--asam-layout-field-gap)</code> 回退，避免继承根部已经计算好的20px；局部 <code>fieldGap=&#39;31px&#39;</code> 或 <code>&#39;0px&#39;</code> 仍有效，显式 density 覆盖优先。<code>toAsamCssVariables</code> 仍按实际对象序列化，缺省字段不会被它新增。嵌套 FormItem 的原生 margin-bottom:0 规则保留，label/content 行高和单行控件高度仍由各组件适配，不把间距变量当高度。</p><p>Row/Col 的 xs/sm/md/lg/xl props 提供响应式列布局。<code>hidden-xs-only</code> 等原生可见性工具类需显式 <code>import &#39;element-plus/theme-chalk/display.css&#39;</code>；ASAM 主样式不自动包含它。使用既定 UnoCSS 工具类的消费项目按自己的扫描和 preset 配置生成 CSS，不能因类名存在就认定样式已加载。响应式列、display.css 隐藏与独立 size 例外均有完整 TS/JS SFC。</p><hr><p>内容来源：<code>apps/docs/src/guides/Theme.mdx</code>。本页由同源指南生成；组件 Demo 与 API 从 <a href="/component-catalog.html">组件目录</a> 查看。</p>`,25)])])}const g=t(o,[["render",i]]);export{m as __pageData,g as default};
